int main(void){
	int n,m;
	int ans=0;
	int x=0,y=0;
	string s;

	cin>>n>>m;
	cin>>s;
	s+="0";

	for(int i=0;i<=n;i++){
		if(s[i]=='0'){
			ans=max(ans,max(x+y-m,y));
			x=0,y=0;
		}
		if(s[i]=='1')x++;
		if(s[i]=='2')y++;
	}

	cout<<ans<<endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int N, M;
    cin >> N >> M;

    string S;
    cin >> S;

    int ng = -1;
    int ok = N;

    auto check = [&](int mid) -> bool {
        const int muji_max = M;
        const int logo_max = mid;

        int muji = muji_max;
        int logo = logo_max;

        for (int i = 0; i < N; i++) {
            if (S[i] == '0') {
                muji = muji_max;
                logo = logo_max;
                continue;
            }

            if (S[i] == '1') {
                if (muji > 0) {
                    muji--;
                    continue;
                }
                if (logo > 0) {
                    logo--;
                    continue;
                }
                return false;
            }

            if (S[i] == '2') {
                if (logo > 0) {
                    logo--;
                    continue;
                }
                return false;
            }
        }

        return true;
    };

    while (ok - ng > 1) {
        int mid = midpoint(ng, ok);
        (check(mid) ? ok : ng) = mid;
    }

    cout << ok << endl;
}
